@startuml

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
  + ItemsDescription : string
}

class PickupVehicle {
  + LicensePlateNumber : string
  + AvailableStorageSpace : int
}

class VolunteerDriver {
  + Name : string
  + DaysAvailable : date[]
}

class DistributionCenter {
  + Address : string
}

class FoodBank {
  + Address : string
}

class SecondHandArticle {
  + RFIDTag : string
  + Description : string
  + Category : ItemCategory
}

class Client {
  + Name : string
  + HomeAddress : string
  + NeededCategories : ItemCategory[]
}

abstract class Employee {
  + FirstName : string
  + LastName : string
}

class H2SEmployee {}

enum ItemCategory {
  BabyClothing
  WomenWinterBoots
  Fridge
  Microwave
  // ... other categories
}

Resident "1" -- "*" PickupRequest
PickupVehicle "0..*" -- "*" PickupRequest
VolunteerDriver "1" -- "*" PickupRequest : assigned by
DistributionCenter "1" -- "*" PickupRequest : receives
FoodBank "1" -- "*" NonPerishableFoodDrop

H2SEmployee "1" -- "*" SecondHandArticle : examines and tags
H2SEmployee "0..*" -- "*" Client : calls to notify about available articles
Client "0..*" -- "*" DeliveryRequest : indicates needed categories
VolunteerDriver "1" -- "*" DeliveryRequest : arranges delivery

@enduml

